 1	import type React from 'react';
 2	import { hide, remove, show } from '@ebay/nice-modal-react';
 3	import type { NiceModalHocProps } from '@ebay/nice-modal-react';
 4	
 5	// Use this instead of {} to avoid ban-types
 6	export type NoProps = Record<string, never>;
 7	
 8	// Map P for component props: void -> NoProps; otherwise P
 9	type ComponentProps<P> = [P] extends [void] ? NoProps : P;
10	
11	// Map P for .show() args: void -> []; otherwise [props: P]
12	type ShowArgs<P> = [P] extends [void] ? [] : [props: P];
13	
14	// Modalized component with static show/hide/remove methods
15	export type Modalized<P, R> = React.ComponentType<ComponentProps<P>> & {
16	  __modalResult?: R;
17	  show: (...args: ShowArgs<P>) => Promise<R>;
18	  hide: () => void;
19	  remove: () => void;
20	};
21	
22	export function defineModal<P, R>(
23	  component: React.ComponentType<ComponentProps<P> & NiceModalHocProps>
24	): Modalized<P, R> {
25	  const c = component as unknown as Modalized<P, R>;
26	  c.show = ((...args: ShowArgs<P>) =>
27	    show(
28	      component as React.FC<ComponentProps<P>>,
29	      args[0] as ComponentProps<P>
30	    ) as Promise<R>) as Modalized<P, R>['show'];
31	  c.hide = () => {
32	    void hide(component as React.FC<ComponentProps<P>>);
33	  };
34	  c.remove = () => remove(component as React.FC<ComponentProps<P>>);
35	  return c;
36	}
37	
38	// Common modal result types for standardization
39	export type ConfirmResult = 'confirmed' | 'canceled';
40	export type DeleteResult = 'deleted' | 'canceled';
41	export type SaveResult = 'saved' | 'canceled';
42	
43	// Error handling utility for modal operations
44	export function getErrorMessage(error: unknown): string {
45	  if (error instanceof Error) {
46	    return error.message;
47	  }
48	  if (typeof error === 'string') {
49	    return error;
50	  }
51	  return 'An unknown error occurred';
52	}

